package com.example.im.security;
import io.jsonwebtoken.Claims; import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtAuthenticationFilter(JwtService jwt){this.jwt=jwt;}
 protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization"); if(h==null||!h.startsWith("Bearer ")){chain.doFilter(req,res);return;} try{String t=h.substring(7);if(!jwt.isType(t,"ACCESS")){chain.doFilter(req,res);return;} Claims c=jwt.parse(t);var a=new UsernamePasswordAuthenticationToken(c.getSubject(),null,List.of());SecurityContextHolder.getContext().setAuthentication(a);chain.doFilter(req,res);}catch(JwtException|IllegalArgumentException e){res.setStatus(401);res.setContentType("application/json;charset=UTF-8");res.getWriter().write("{\"code\":401,\"message\":\"Token无效或已过期\"}");}}
}
